// The brain shared by all 15 Upcoming card designs and the popup. You do not edit this file:
// everything you change lives in site/upcomingConfig.js.
import { Component, useEffect, useRef, useState } from 'react';
import { Icon } from './Icons';
import { LINKS, pastEvents } from '../data/site';
import { dateFromText, getPast, toDate } from './time';
import * as C from './upcomingConfig';

/* ---------- settings (read from upcomingConfig.js, with safe fallbacks) ---------- */
export const TYPES = ['hackathon', 'workshop', 'online'];
export const TYPE = TYPES.includes(C.EVENT_TYPE) ? C.EVENT_TYPE : 'hackathon';
export const EVENT_NAME = String(C.EVENT_NAME || '').trim();

const T = { from: toDate(C.TEASER_FROM), start: toDate(C.EVENT_START), end: toDate(C.HIDE_AFTER) };
// when the card and the popup go away by themselves: HIDE_AFTER, else 2 days after EVENT_START, else never (the switch decides)
const END = T.end || (T.start ? new Date(T.start.getTime() + 2 * 864e5) : null);
const stillOn = (now) => !END || now < END.getTime();

/* is the mystery card (and with it the popup) live right now? */
export const isTeaserLive = () => !!C.SHOW_UPCOMING && stillOn(Date.now());

/* ---------- which design is it? (popup + matching card) ---------- */
const LIST = Array.isArray(C.DESIGNS) && C.DESIGNS.length ? C.DESIGNS : [['radar', 1]];
// finished events (with photos) dated on or after ROTATION_FROM: each one moves the next event on to the next design
const finishedSince = () => {
  const from = String(C.ROTATION_FROM || '');
  return getPast(pastEvents).filter((e) => { const d = e.sortDate || dateFromText(e.date); return !!d && d >= from; }).length;
};
export function getDesign() {
  let q = null;
  try { q = Number(new URLSearchParams(window.location.search).get('design')); } catch { /* no address bar: ignore */ }
  const force = Math.round(Number(C.FORCE_DESIGN)) || 0;
  let i;
  if (q >= 1 && q <= LIST.length) i = Math.round(q) - 1;          // ?design=4 preview
  else if (force >= 1 && force <= LIST.length) i = force - 1;     // locked in upcomingConfig.js
  else i = finishedSince() % LIST.length;                         // automatic: the next design for every new event
  const [popup, card] = LIST[i];
  return { n: i + 1, popup, card: Math.min(5, Math.max(1, Math.round(Number(card)) || 1)), preview: q >= 1 && q <= LIST.length ? Math.round(q) : 0 };
}

/* ---------- words for each kind of event ---------- */
export const COPY = {
  hackathon: {
    flag: 'Signal detected', file: 'Classified', tag: 'CLASSIFIED', noun: 'hackathon',
    title: 'Name will be announced soon', lede: 'Something big is coming.',
    desc: 'Every detail is classified for now. The name, dates, format and prizes will all be announced soon.',
    wait: 'Timer starts when the dates are announced', status: 'Compiling the unknown',
    boxes: [['Format', 8], ['Rounds', 9], ['Team size', 7], ['Theme', 9], ['Prizes', 8], ['Registration', 10]],
  },
  workshop: {
    flag: 'New session loading', file: 'Locked', tag: 'LOCKED', noun: 'workshop',
    title: 'Workshop name will be announced soon', lede: 'A new workshop is on the way.',
    desc: 'The topic, speaker, date and seats are locked for now. Everything will be announced soon.',
    wait: 'Timer starts when the date is announced', status: 'Preparing the session',
    boxes: [['Topic', 9], ['Speaker', 8], ['Duration', 7], ['Venue', 8], ['Seats', 5], ['Registration', 10]],
  },
  online: {
    flag: 'Going live soon', file: 'Online', tag: 'ONLINE', noun: 'online event',
    title: 'Event name will be announced soon', lede: 'Something is going live online.',
    desc: 'The platform, host, date and joining link will all be announced soon. Join from anywhere.',
    wait: 'Timer starts when the date is announced', status: 'Warming up the stream',
    boxes: [['Platform', 9], ['Host', 8], ['Duration', 7], ['Join link', 9], ['Certificate', 10], ['Registration', 10]],
  },
};

const reduced = () => !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const GLYPHS = '0123456789ABCDEF#$%&*+<>/';
const rnd = (n) => Array.from({ length: n }, () => GLYPHS[Math.floor(Math.random() * GLYPHS.length)]).join('');
export const HEX = Array.from({ length: 36 }, (_, i) => `0x${(((i + 3) * 2654435761) >>> 24).toString(16).toUpperCase().padStart(2, '0')}`).join('  ');

function useNow() {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  return now;
}
function parts(ms) {
  let r = Math.max(0, ms);
  const d = Math.floor(r / 864e5); r -= d * 864e5;
  const h = Math.floor(r / 36e5); r -= h * 36e5;
  const m = Math.floor(r / 6e4); r -= m * 6e4;
  return { d, h, m, s: Math.floor(r / 1000) };
}

/* flickering random characters, used for everything that is "classified" */
export function Cipher({ len, speed = 150 }) {
  const [s, setS] = useState(() => (reduced() ? '█'.repeat(len) : rnd(len)));
  useEffect(() => {
    if (reduced()) return undefined;
    const id = setInterval(() => setS(rnd(len)), speed);
    return () => clearInterval(id);
  }, [len, speed]);
  return <span aria-hidden="true">{s}</span>;
}

/* the text inside one detail box, for every state (hidden, scrambling, denied, typed out) */
export function FieldValue({ f }) {
  if (f.state === 'open') {
    return (
      <>
        {f.typing && <span className="tc-sr">{f.text}</span>}
        <span aria-hidden={f.typing ? 'true' : undefined}>{f.shownText}</span>
        {f.showCursor && <span className="tc-cur" aria-hidden="true">_</span>}
      </>
    );
  }
  if (f.state === 'work') return <Cipher len={f.len} speed={45} />;
  if (f.state === 'denied') return 'ACCESS DENIED';
  return 'Will be revealed soon';
}

/* everything a card design needs: timer, detail boxes, progress, the decrypt button */
export function useTeaser() {
  const now = useNow();
  const copy = COPY[TYPE];
  const details = (C.DETAILS && C.DETAILS[TYPE]) || {};
  const detailOf = (k) => String(details[k] || '');
  const hasDetails = copy.boxes.some(([k]) => detailOf(k));

  const [phase, setPhase] = useState('idle'); // idle -> work -> denied -> idle   (or work -> typing -> done when details are set)
  const [prog, setProg] = useState(0);
  const [counts, setCounts] = useState(() => copy.boxes.map(() => 0));
  const ids = useRef([]);
  useEffect(() => {
    const list = ids.current;
    return () => list.forEach((i) => { clearTimeout(i); clearInterval(i); });
  }, []);

  const visible = !!C.SHOW_UPCOMING && stillOn(now);

  const decrypt = () => {
    if (phase !== 'idle') return;
    const later = (fn, ms) => { ids.current.push(setTimeout(fn, ms)); };
    const deny = () => { setPhase('denied'); later(() => setPhase('idle'), 2000); };
    const reveal = () => {
      setProg(100);
      if (reduced()) { setPhase('done'); return; }
      setPhase('typing');
      const t0 = Date.now();
      const tick = setInterval(() => {
        const el = Date.now() - t0;
        const next = copy.boxes.map(([k], i) => Math.max(0, Math.min(detailOf(k).length, Math.floor((el - i * 260) / (C.TYPE_MS || 45)))));
        setCounts(next);
        if (copy.boxes.every(([k], i) => next[i] >= detailOf(k).length)) { clearInterval(tick); setPhase('done'); }
      }, 35);
      ids.current.push(tick);
    };
    if (reduced()) { if (hasDetails) reveal(); else { setProg(99); deny(); } return; }
    setPhase('work');
    setProg(0);
    const t0 = Date.now();
    const tick = setInterval(() => setProg(Math.min(99, Math.round(((Date.now() - t0) / 2600) * 99))), 60);
    ids.current.push(tick);
    later(() => { clearInterval(tick); if (hasDetails) reveal(); else deny(); }, 2600);
  };

  // countdown: asleep until a start date is set, then it counts down, then it says "live"
  const startMs = T.start ? T.start.getTime() : null;
  const waiting = startMs === null;
  const counting = startMs !== null && now < startMs;
  const live = startMs !== null && now >= startMs;
  const c = counting ? parts(startMs - now) : null;
  const cells = c
    ? [['Days', c.d], ['Hours', c.h], ['Mins', c.m], ['Secs', c.s]]
    : [['Days', '--'], ['Hours', '--'], ['Mins', '--'], ['Secs', '--']];

  let compile = C.COMPILING;
  if (counting && T.from && T.from.getTime() < startMs) {
    compile = Math.max(1, Math.min(99, Math.round(((now - T.from.getTime()) / (startMs - T.from.getTime())) * 100)));
  } else if (live) {
    compile = 99;
  }
  const open = phase === 'typing' || phase === 'done';
  const shown = open ? 100 : phase === 'idle' ? compile : prog;
  const status = open ? 'Decrypted' : phase === 'denied' ? 'Access denied' : phase === 'work' ? 'Decrypting' : copy.status;
  const btn = open ? 'Decrypted' : phase === 'denied' ? 'Access denied' : phase === 'work' ? `Decrypting… ${prog}%` : 'Try to decrypt';

  const fields = copy.boxes.map(([k, len], i) => {
    const text = detailOf(k);
    const isOpen = !!text && open;
    const typing = phase === 'typing';
    return {
      k, len, text,
      state: isOpen ? 'open' : phase === 'work' ? 'work' : phase === 'denied' ? 'denied' : 'idle',
      typing: isOpen && typing,
      shownText: isOpen && typing ? text.slice(0, counts[i]) : text,
      showCursor: isOpen && typing && counts[i] < text.length,
    };
  });

  return {
    visible, type: TYPE, copy, name: EVENT_NAME, title: EVENT_NAME || copy.title,
    phase, decrypt, open, shown, status, btn, fields, cells, counting, waiting, live, c, hex: HEX,
    label: `Something big is coming. Every detail will be revealed soon.`,
  };
}

/* the buttons under every card: Get notified, Try to decrypt, Instagram */
export function Actions({ t, className = '' }) {
  return (
    <div className={`s-actions ${className}`}>
      <a className="s-btn s-btn-light" href={LINKS.joinForm} target="_blank" rel="noopener noreferrer">
        <Icon.Bell size={16} /> Get notified
      </a>
      <button type="button" className="s-btn s-btn-ghost s-mys-dec" onClick={t.decrypt} disabled={t.phase !== 'idle'}>
        <Icon.Terminal size={16} /> {t.btn}
      </button>
      <a className="s-link" href={LINKS.instagram} target="_blank" rel="noopener noreferrer">
        <Icon.Instagram size={16} /> Get updates on Instagram
      </a>
    </div>
  );
}

/* if a lazily loaded design fails to load (bad network), show nothing instead of breaking the page */
export class Guard extends Component {
  constructor(props) { super(props); this.state = { bad: false }; }
  static getDerivedStateFromError() { return { bad: true }; }
  componentDidCatch() { /* nothing to report: the page simply goes on without the card */ }
  render() { return this.state.bad ? (this.props.fallback ?? null) : this.props.children; }
}
